package com.cloudscheduler.server.controller;
import com.cloudscheduler.core.model.*; import com.cloudscheduler.core.scheduler.SchedulingStrategy; import com.cloudscheduler.server.service.SchedulerService; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1") public class ApiController { private final SchedulerService s; public ApiController(SchedulerService x){s=x;} @GetMapping("/tasks") Collection<Task> tasks(){return s.tasks();} @PostMapping("/tasks") ResponseEntity<Task> task(@RequestBody Task t){return ResponseEntity.status(HttpStatus.CREATED).body(s.add(t));} @GetMapping("/vms") Collection<VirtualMachine> vms(){return s.vms();} @PostMapping("/vms") ResponseEntity<VirtualMachine> vm(@RequestBody VirtualMachine v){return ResponseEntity.status(HttpStatus.CREATED).body(s.add(v));} @GetMapping("/phones") Collection<Phone> phones(){return s.phones();} @PostMapping("/phones/connect") ResponseEntity<Phone> phone(@RequestBody Phone p){return ResponseEntity.status(HttpStatus.CREATED).body(s.add(p));} @PostMapping("/scheduler/schedule") List<Task> schedule(@RequestParam(name="strategy", defaultValue="BALANCED") SchedulingStrategy strategy){return s.schedule(strategy);}@GetMapping("/health") Map<String,String> health(){return Map.of("status","UP");} }
